-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Grundprinzipien > - Red-Green-Refactor-Zyklus

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist der Red-Green-Refactor-Zyklus das zentrale Prinzip der testgetriebenen Entwicklung (TDD)?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert den TDD-Prozess"}, {"text": "Nein", "correct": false, "because": "Kernprinzip von TDD"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Red-Green-Refactor-Zyklus ohne automatisierte Tests effizient durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung sorgt für schnelle Iterationen"}, {"text": "Ja", "correct": false, "because": "Manuell ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen im Red-Green-Refactor-Zyklus alle Tests in der Rot-Phase fehlschlagen?', 2, '[{"text": "Ja", "correct": true, "because": "Neuer Test schlägt ohne Code fehl"}, {"text": "Nein", "correct": false, "because": "Rot-Phase definiert Fehlschlag"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Refactoring-Schritte im Red-Green-Refactor-Zyklus die Funktionalität der Software verändern?', 2, '[{"text": "Nein", "correct": true, "because": "Refactoring bewahrt Funktion"}, {"text": "Ja", "correct": false, "because": "Nur Strukturänderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, den Red-Green-Refactor-Zyklus zu überspringen und direkt mit der Implementierung zu beginnen?', 2, '[{"text": "Nein", "correct": true, "because": "Zyklus ist TDD-Grundlage"}, {"text": "Ja", "correct": false, "because": "Widerspricht TDD"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt im Red-Green-Refactor-Zyklus beginnt mit der Erstellung eines neuen Tests?', 2, '[{"text": "Rot-Phase", "correct": true, "because": "Test wird geschrieben und schlägt fehl"}, {"text": "Grün-Phase", "correct": false, "because": "Code wird angepasst"}, {"text": "Refactor-Phase", "correct": false, "because": "Struktur verbessert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Grün-Phase im Red-Green-Refactor-Zyklus?', 3, '[{"text": "Den Test erfolgreich machen", "correct": true, "because": "Code wird minimal angepasst"}, {"text": "Code-Optimierung", "correct": false, "because": "Refactoring-Schritt"}, {"text": "Fehlerlokalisierung", "correct": false, "because": "Rot-Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase im Red-Green-Refactor-Zyklus verbessert die Code-Struktur?', 2, '[{"text": "Refactor-Phase", "correct": true, "because": "Struktur ohne Funktionsänderung"}, {"text": "Rot-Phase", "correct": false, "because": "Test fehlschlägt"}, {"text": "Grün-Phase", "correct": false, "because": "Test wird bestanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wird im Red-Green-Refactor-Zyklus durch die Rot-Phase betont?', 2, '[{"text": "Test vor Code", "correct": true, "because": "Test definiert Anforderung"}, {"text": "Maximale Abdeckung", "correct": false, "because": "Nicht primär"}, {"text": "Code-Optimierung", "correct": false, "because": "Refactoring"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug ist im Red-Green-Refactor-Zyklus entscheidend, um den Übergang zwischen den Phasen zu sichern?', 2, '[{"text": "Test-Framework", "correct": true, "because": "Automatisiert Testausführung"}, {"text": "Debugger", "correct": false, "because": "Fehleranalyse"}, {"text": "Compiler", "correct": false, "because": "Nur Übersetzung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Phasen umfasst der Red-Green-Refactor-Zyklus in TDD?', 4, '[{"text": "Rot-Phase", "correct": true, "because": "Test fehlschlägt"}, {"text": "Grün-Phase", "correct": true, "because": "Test erfolgreich"}, {"text": "Refactor-Phase", "correct": true, "because": "Struktur verbessert"}, {"text": "Dokumentations-Phase", "correct": false, "because": "Nicht Teil des Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien werden im Red-Green-Refactor-Zyklus betont?', 3, '[{"text": "Test vor Code", "correct": true, "because": "Rot beginnt mit Test"}, {"text": "Minimale Implementierung", "correct": true, "because": "Grün nur nötiger Code"}, {"text": "Maximale Dokumentation", "correct": false, "because": "Nicht primär"}, {"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Refactoring"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Red-Green-Refactor-Zyklus in TDD?', 3, '[{"text": "Schnelle Fehlererkennung", "correct": true, "because": "Rot-Phase zeigt Probleme"}, {"text": "Hohe Codequalität", "correct": true, "because": "Refactoring verbessert"}, {"text": "Langsamere Iterationen", "correct": false, "because": "Eher schneller"}, {"text": "Klarer Entwicklungsprozess", "correct": true, "because": "Strukturierter Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es im Red-Green-Refactor-Zyklus?', 4, '[{"text": "Hoher Testaufwand", "correct": true, "because": "Tests vorab schreiben"}, {"text": "Komplexität bei Refactoring", "correct": true, "because": "Strukturänderung"}, {"text": "Keine Automatisierung", "correct": false, "because": "Tests automatisiert"}, {"text": "Unklare Anforderungen", "correct": true, "because": "Tests schwer definierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind im Red-Green-Refactor-Zyklus entscheidend?', 3, '[{"text": "Fehlschlagende Tests", "correct": true, "because": "Rot-Phase startet"}, {"text": "Minimale Code-Änderung", "correct": true, "because": "Grün-Phase fokussiert"}, {"text": "Manuelle Überprüfung", "correct": false, "because": "Automatisierung zentral"}, {"text": "Strukturverbesserung", "correct": true, "because": "Refactor-Phase"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Rot-Phase beginnt mit einem erfolgreichen Test. b) Der Red-Green-Refactor-Zyklus ist iterativ.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Rot mit Fehlschlag, Zyklus iterativ"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Grün-Phase optimiert den Code. b) Refactoring bewahrt die Funktionalität.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Grün macht Test erfolgreich, Refactoring bewahrt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Red-Green-Refactor-Zyklus erfordert automatisierte Tests. b) Refactoring ist in TDD optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests automatisiert, Refactoring zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Rot-Phase zeigt Fehler im Code. b) Der Zyklus kann ohne Tests funktionieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rot zeigt Fehler, Tests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Red-Green-Refactor-Zyklus fördert hohe Codequalität. b) Die Grün-Phase ist der letzte Schritt im Zyklus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität steigt, Refactoring folgt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

